                  <img src={logo} alt="logo" width="80" height="80" className="me-2" /></a> 
            </div> 
          </div>    
      </header>

<footer className="text-body-secondary py-5">
        <div className="container">
          <p className="float-end mb-1">
            <a href="#">Voltar ao topo</a>
          </p>
          <p className="mb-1">
            Minha Vitrine &copy; 2025
          </p>
        </div>
      </footer>
    </div>
  );
}

export default App;
